"""Embed four checked vectors into the same open standalone source."""
from pathlib import Path
import json,hashlib,difflib
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).resolve().parent
baseline=HERE/'baseline-reviewed-source.tex';s=baseline.read_text();assert hashlib.sha256(baseline.read_bytes()).hexdigest()=='546ac4c6050bef4b4c97c28ede46789de1b0996e141c11e5421322a021e8057c'
s=s.replace(r'\hypersetup{hidelinks}',r'\usepackage{xcolor}'+'\n'+r'\hypersetup{hidelinks}',1)
def figure(name,caption,label):return '\n'+r'\begin{figure}[htbp]\centering'+'\n'+(HERE/(name+'.inline.tex')).read_text()+'\n'+r'\caption{'+caption+'}\n'+r'\label{'+label+'}\n'+r'\end{figure}'+'\n'
cap=r'''Inflation reductions under the history cap coexist with predictive-error and query-failure costs. Both panels show the same twelve primary robust-estimator source/rule means at 10\% capacity, averaging three fixed fitting seeds on 1,000 shared listings per source. Colors denote sources and shapes denote query rules. Positive inflation reduction is favorable; positive attacked-MAE change (a) and failed-query change (b) are unfavorable. Error changes are within-source percentages; failure changes are percentage points per listing. These are descriptive means, without confidence intervals; nonconverged responses remain included. The full numerical comparison is in Table~\ref{tab:cap_responses}.'''
cost=r'''Cost deterrence accompanies the local feedback reversal, whose sign varies across fitting seeds. Synthetic robust/suppression/top-$B$ on the same 1,000 records and three fitting seeds. (a) Zero-cost markers are directly observed mean hidden counts. Positive-cost line segments are utility/regret identification bounds on the mean count, not confidence intervals; no midpoint estimate is asserted. (b) Symbols retain all three paired seed effects, measured as no-feedback minus feedback inflation; horizontal black strokes are seed means and positive values favor feedback. The four categorical scenarios are zero, uniform 0.005, uniform 0.02 and heterogeneous $0.02h_i$, with $h_i\in[0.5,1.5)$. No interpolation between scenarios or new uncertainty claim is made. All returned nonconverged profiles are retained.'''
variance=r'''Fitting randomness dominates the remaining conditional uncertainty after full MUCars evaluation. Bars show absolute seed-main, batch-main and interaction variances for the masking/suppression feedback contrast under both allocators; labels give the seed-main share. Ten fitting seeds are shared. Capped evaluation uses ten equal 100-record batches; uncapped evaluation uses 107 record-weighted batches containing 10,672 listings. Both the outcome matrix and weights change, so these are distinct conditional designs, not a pure sample-size experiment. Components condition on the fixed training records and fitted models; they do not quantify training-population uncertainty or establish equivalence.'''
envelope=r'''The restricted final-record envelope's honest-error cost is concentrated on naturally incomplete categorical records. (a) Among each source's original 1,000 listings, complete/incomplete/abstained counts are 800/1/199 for JUCars and 971/28/1 for MUCars. Complete means all three declared categorical fields are observed; missing mileage causes abstention. Complete covered records have singleton completion sets and exactly zero change. (b) Every MUCars fitting seed is shown for all 999 covered records and its nested 28-record naturally incomplete subset; lines link the two descriptive means for the same frozen model, without interpolation or confidence intervals. Positive honest-MAE change is worse; units are MUCars currency. Mileage remains observed and fixed. This does not validate the full four-field game or unseen-category coverage.'''
anchor='The consequential finding is the joint cost:';assert anchor in s;s=s.replace(anchor,'Figure~\\ref{fig:cap_tradeoffs} displays the two principal trade-off coordinates.\n'+figure('cap-tradeoffs',cap,'fig:cap_tradeoffs')+'\n'+anchor,1)
anchor='The reversal accompanies strong concealment deterrence.';assert anchor in s;s=s.replace(anchor,'Figure~\\ref{fig:cost_mechanism} separates concealment deterrence from the paired feedback effects.\n'+figure('cost-mechanism',cost,'fig:cost_mechanism')+'\n'+anchor,1)
anchor='The accompanying \\path{audit-protocol/} artifact';assert anchor in s;s=s.replace(anchor,'Figure~\\ref{fig:uncertainty_components} shows absolute components alongside their shares.\n'+figure('uncertainty-components',variance,'fig:uncertainty_components')+'\n'+anchor,1)
anchor='Each JUCars model evaluates 806 completions;';assert anchor in s;s=s.replace(anchor,'Figure~\\ref{fig:envelope_boundary} links the coverage boundary to the concentration of error costs.\n'+figure('envelope-boundary',envelope,'fig:envelope_boundary')+'\n'+anchor,1)
s=s.replace('''records. Mileage is observed and fixed, so this is not a tested four-field
replacement''','''records (Figure~\\ref{fig:envelope_boundary}). Mileage is observed and fixed,
so this is not a tested four-field replacement''',1)
target=ROOT/'paper/innovation-addendum-v1.tex';target.write_text(s)
(HERE/'manuscript-changes.patch').write_text(''.join(difflib.unified_diff(baseline.read_text().splitlines(True),s.splitlines(True),fromfile='teacher-v4',tofile='results-visual-v5')))
receipt=dict(status='vectors_embedded_pending_compile',figure_count=6,new_figure_count=4,new_training_runs=0,source_sha256=hashlib.sha256(target.read_bytes()).hexdigest(),script_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),labels=['fig:cap_tradeoffs','fig:cost_mechanism','fig:uncertainty_components','fig:envelope_boundary'])
(HERE/'manuscript-revision-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(receipt)
